const knowledgeUnitMatch = `-- name: KnowledgeUnitMatch :many
SELECT u.id,u.uuid,u.question,u.answer,u.category,u.visibility,u.brand_id,u.department_id,
 a.uuid AS article_uuid,
 max((1-(q.embedding <=> $3::vector)))::double precision AS score
FROM knowledge_unit_questions q
JOIN knowledge_units u ON u.organization_id=q.organization_id AND u.id=q.unit_id
LEFT JOIN knowledge_articles a ON a.organization_id=u.organization_id AND a.id=u.article_id
WHERE q.organization_id=$1 AND u.locale=$2 AND u.embedding_model=$4
 AND (NOT $5::boolean OR u.visibility='public')
 AND (u.brand_id IS NULL OR u.brand_id=$6::uuid)
 AND (u.department_id IS NULL OR u.department_id=$7::bigint)
GROUP BY u.id,a.uuid
ORDER BY score DESC,u.id LIMIT 10
`

type KnowledgeUnitMatchParams struct {
	OrganizationID int64              `json:"organization_id"`
	Locale         string             `json:"locale"`
	Embedding      vectorstore.Vector `json:"embedding"`
	EmbeddingModel string             `json:"embedding_model"`
	PublicOnly     bool               `json:"public_only"`
	BrandID        pgtype.UUID        `json:"brand_id"`
	DepartmentID   pgtype.Int8        `json:"department_id"`
}

type KnowledgeUnitMatchRow struct {
	ID           int64       `json:"id"`
	Uuid         uuid.UUID   `json:"uuid"`
	Question     string      `json:"question"`
	Answer       string      `json:"answer"`
	Category     string      `json:"category"`
	Visibility   string      `json:"visibility"`
	BrandID      pgtype.UUID `json:"brand_id"`
	DepartmentID pgtype.Int8 `json:"department_id"`
	ArticleUuid  pgtype.UUID `json:"article_uuid"`
	Score        float64     `json:"score"`
}

// Scope: org-wide rows always qualify, brand/department rows only for the same
// brand/department. The caller prefers the most specific match.
func (q *Queries) KnowledgeUnitMatch(ctx context.Context, arg KnowledgeUnitMatchParams) ([]KnowledgeUnitMatchRow, error) {
	rows, err := q.db.Query(ctx, knowledgeUnitMatch,
		arg.OrganizationID,
		arg.Locale,
		arg.Embedding,
		arg.EmbeddingModel,
		arg.PublicOnly,
		arg.BrandID,
		arg.DepartmentID,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []KnowledgeUnitMatchRow{}
	for rows.Next() {
		var i KnowledgeUnitMatchRow
		if err := rows.Scan(
			&i.ID,
			&i.Uuid,
			&i.Question,
			&i.Answer,
			&i.Category,
			&i.Visibility,
			&i.BrandID,
			&i.DepartmentID,
			&i.ArticleUuid,
			&i.Score,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

